            f"lessons/{encode_path_param(lesson_id)}/completions",
            method="POST",
            json={
                "answers": convert_and_respect_annotation_metadata(
                    object_=answers, annotation=typing.Dict[str, LessonCompletionRequestAnswersValue], direction="write"
                ),
                "startedAt": started_at,
                "stepTimings": convert_and_respect_annotation_metadata(
                    object_=step_timings,
                    annotation=typing.Dict[str, LessonCompletionRequestStepTimingsValue],
                    direction="write",
                ),
                "timeZone": time_zone,
            },
            headers={
                "content-type": "application/json",
            },
